"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7701],{17701:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/towards-midnight.png\\"\\n          title=\\"0시를 향하여\\"\\n          author=\\"애거서 크리스티\\"\\n          publisher=\\"황금가지\\"\\n          publishedDate=\\"2013-05-27\\"\\n          isbn=\\"9788982737046\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n진범의 반전과 그 뒤 진정한 흑막이 충격적인 결말을 가져오는 작품이다.\\n다층적 트릭과 반전으로 독자를 두 번 속이는 정교한 트릭이다. 이것이 바로 ```트릭의 여왕```.  \\n<br>\\n인간 내면의 어둠을 잘 나타낸 심리 묘사도 돋보인다.  \\n<br>\\n원제도 <mark>Towards Zero</mark>인데, 살인사건을 이야기의 ```시작```이 아닌 ```종착점```으로 보기 때문인 것 같다.\\n즉, 이 소설의 관점에서 살인사건은 갑자기 발생하는 돌발 사건이 아니라, 서로 관계없어 보이던 여러 인물의 과거, 욕망, 갈등, 계획들이 마치 여러 개의 강물이 하나의 바다로 모여들듯 치밀하게 ```살인```이라는 단 하나의 정점, 즉 **\'0시(Zero Hour)\'**를 향해 흘러가고 수렴한 결과물이라는 것이다.  \\n<br>\\n<mark>애거서 크리스티</mark>의 진면목을 볼 수 있는 작품이었다."}')}}]);